import {accountCardView} from './core.js';
import {sampleManagedGroups,filterManagedGroups,changeSampleGroupMode} from './group-manager-model.js';
const el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e};
const button=(text,fn,cls='button quiet')=>{const b=el('button',cls,text);b.type='button';b.onclick=fn;return b};
const workspace={groups:[],samples:[],accounts:new Set(),selected:new Set(),loaded:new Set()};
export function openGroupManager(state){
 if(document.getElementById('groupManagerDialog'))return;
 const w=workspace;let filter='all',query='',opener=document.activeElement;
 const accounts=state.profiles.map(p=>{const v=accountCardView(p);return {id:p.id,name:v.authenticated?v.nickname:p.name,detail:[v.phoneNumber,p.remark,p.sleeping?'休眠中':v.authenticated?'已登录':'尚未登录'].filter(Boolean).join(' · ')}}).concat(w.samples);
 const valid=new Set(accounts.map(a=>a.id));w.accounts=new Set([...w.accounts].filter(id=>valid.has(id)));w.selected=new Set([...w.selected].filter(id=>w.groups.some(g=>g.id===id&&w.accounts.has(g.accountId))));
 const d=el('dialog','bulk-dialog group-manager');d.id='groupManagerDialog';d.setAttribute('aria-labelledby','groupManagerTitle');
 d.innerHTML=`<header class="bulk-dialog-heading"><strong id="groupManagerTitle">WhatsApp · 群组管理</strong><button type="button" class="icon-button gm-close" aria-label="关闭群组窗口">×</button></header><p class="gm-notice">交互演示 · 未连接 WhatsApp。示例操作不会修改真实群组。</p><div class="gm-columns"><section class="gm-column"><h3>选择 WhatsApp 账户</h3><p class="gm-muted">支持多选账户</p><div class="gm-account-all"></div><div class="gm-accounts gm-scroll"></div><div class="gm-account-tools"></div></section><section class="gm-column"><h3>选择群组</h3><p class="gm-muted">已开群：全员可发言 · 已闭群：仅管理员发言</p><div class="gm-tabs" role="group" aria-label="群组分类"></div><input class="gm-search" aria-label="搜索群组" placeholder="搜索群组名称"><div class="gm-all"></div><div class="gm-groups gm-scroll"></div><div class="gm-load"></div></section><section class="gm-column"><h3>操作面板</h3><div class="gm-actions"></div><p class="gm-muted">全员禁言：仅管理员发言。开启发言：所有成员可发言。</p><div class="gm-summary"></div><h3>操作详情 <span class="gm-count"></span></h3><div class="gm-details gm-scroll"></div><p class="gm-feedback" role="status"></p></section></div>`;
 const q=s=>d.querySelector(s),accountName=id=>accounts.find(a=>a.id===id)?.name||'账户';
 const visible=()=>filterManagedGroups(w.groups,w.accounts,filter,query),chosen=()=>w.groups.filter(g=>w.selected.has(g.id)&&w.accounts.has(g.accountId));
 function checkRow(label,checked,change,detail=''){const row=el('label','gm-row'),input=el('input');input.type='checkbox';input.checked=checked;input.onchange=()=>change(input.checked);const text=el('span','gm-identity');text.append(el('strong','',label));if(detail)text.append(el('small','',detail));row.append(input,text);return row}
 function allRow(host,items,isSelected,toggle,label){const count=items.filter(isSelected).length,row=checkRow(label+' '+count+' / '+items.length,items.length>0&&count===items.length,toggle);row.querySelector('input').indeterminate=count>0&&count<items.length;row.querySelector('input').disabled=!items.length;host.replaceChildren(row)}
 function setAccount(id,on){on?w.accounts.add(id):w.accounts.delete(id);if(!on)for(const g of w.groups)if(g.accountId===id)w.selected.delete(g.id)}
 function renderAccounts(){const host=q('.gm-accounts');host.replaceChildren();for(const a of accounts)host.append(checkRow(a.name,w.accounts.has(a.id),on=>{setAccount(a.id,on);render()},a.detail));if(!accounts.length)host.append(el('p','gm-empty','暂无账户，请在主界面新增会话，或载入示例账户。'));allRow(q('.gm-account-all'),accounts,a=>w.accounts.has(a.id),on=>{accounts.forEach(a=>setAccount(a.id,on));render()},'全部账户')}
 function renderGroups(){const host=q('.gm-groups'),rows=visible();host.replaceChildren();for(const g of rows)host.append(checkRow(g.name,w.selected.has(g.id),on=>{on?w.selected.add(g.id):w.selected.delete(g.id);renderGroups();renderDetails()},accountName(g.accountId)+' · '+(g.closed?'已闭群':'已开群')));if(!rows.length)host.append(el('p','gm-empty',!w.accounts.size?'请先选择左侧账户':w.groups.some(g=>w.accounts.has(g.accountId))?'没有符合条件的群组':'尚未读取真实群组，可载入示例体验。'));allRow(q('.gm-all'),rows,g=>w.selected.has(g.id),on=>{for(const g of rows)on?w.selected.add(g.id):w.selected.delete(g.id);renderGroups();renderDetails()},'全选当前列表');q('.gm-tabs').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));load.disabled=![...w.accounts].some(id=>!w.loaded.has(id))}
 function renderDetails(){const rows=chosen(),host=q('.gm-details');host.replaceChildren();q('.gm-count').textContent='（'+rows.length+'）';for(const g of rows){const card=el('div','gm-detail');card.append(el('strong','',g.name),el('small','',accountName(g.accountId)),el('span',g.closed?'gm-closed':'gm-open',g.closed?'已闭群 · 仅管理员发言':'已开群 · 所有成员可发言'));if(g.result)card.append(el('small','gm-result',g.result));host.append(card)}if(!rows.length)host.append(el('p','gm-empty','选择群组后，操作详情将显示在这里。'));mute.disabled=!rows.some(g=>g.admin&&!g.closed);unmute.disabled=!rows.some(g=>g.admin&&g.closed);q('.gm-summary').textContent='已选 '+rows.length+' 个群组 · 已开群 '+rows.filter(g=>!g.closed).length+' · 已闭群 '+rows.filter(g=>g.closed).length}
 function apply(closed){const targets=new Set(chosen().filter(g=>g.closed!==closed).map(g=>g.id));const count=changeSampleGroupMode(w.groups,targets,closed);renderGroups();renderDetails();q('.gm-feedback').textContent='已模拟'+(closed?'全员禁言':'开启发言')+'：'+count+' 个示例群组。未修改真实 WhatsApp。'}
 const mute=button('全员禁言',()=>apply(true),'button blue'),unmute=button('开启发言',()=>apply(false),'button quiet');q('.gm-actions').append(mute,unmute);
 const load=button('载入所选账户的示例群组',()=>{for(const id of w.accounts)if(!w.loaded.has(id)){w.groups.push(...sampleManagedGroups(id));w.loaded.add(id)}render()});q('.gm-load').append(load);
 q('.gm-account-tools').append(button('载入示例账户',()=>{if(!w.samples.length){w.samples.push({id:'gm-demo-1',name:'工作账户 · 示例',detail:'仅用于演示'},{id:'gm-demo-2',name:'备用账户 · 示例',detail:'仅用于演示'});accounts.push(...w.samples)}for(const a of w.samples)w.accounts.add(a.id);render()}));
 for(const [id,label] of [['all','全部'],['open','已开群'],['closed','已闭群']]){const b=button(label,()=>{filter=id;renderGroups()},'');b.dataset.filter=id;q('.gm-tabs').append(b)}
 q('.gm-search').oninput=e=>{query=e.target.value;renderGroups()};
 function render(){renderAccounts();renderGroups();renderDetails()}
 function fit(){const b=document.querySelector('.app-shell').getBoundingClientRect(),left=Math.max(0,b.left),top=Math.max(0,b.top),aw=Math.max(0,Math.min(innerWidth,b.right)-left),ah=Math.max(0,Math.min(innerHeight,b.bottom)-top),width=Math.max(0,Math.min(1380,aw-24)),height=Math.max(0,Math.min(800,ah-24));Object.assign(d.style,{width:width+'px',height:height+'px',left:(left+(aw-width)/2)+'px',top:(top+(ah-height)/2)+'px'})}
 const resize=new ResizeObserver(fit);function close(){d.close()}
 q('.gm-close').onclick=close;d.onclose=()=>{resize.disconnect();window.removeEventListener('resize',fit);d.remove();opener?.isConnected&&opener.focus()};document.body.append(d);render();d.showModal();fit();resize.observe(document.querySelector('.app-shell'));window.addEventListener('resize',fit);q('.gm-close').focus();
}
